/* Plot Dataset v4 typed presentation model. Scientific values and identities
 * arrive through CORE bounded Dataset/Curve Source access; this model owns
 * only a disposable view. Projection reuses Native2D C world/device geometry. */
#include "gx2d_plot_v4.h"
#include "gx2d.h"
#include <cairo.h>
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <fstream>
#include <limits>
#include <map>
#include <memory>
#include <set>
#include <stdexcept>
#include <string>
