 if(hasStroke){for(size_t i=2;i+1<xy.size();i+=2)if(segmentDistance(x,y,xy[i-2],xy[i-1],xy[i],xy[i+1])<=tolerance)return true;if(type=="polygon"&&xy.size()>=6&&segmentDistance(x,y,xy[0],xy[1],xy[xy.size()-2],xy.back())<=tolerance)return true;}return false;
